KG42.register("rules-fa5c14c4c610fc42c845ca3e",{"id":"47-electricity_hydrogen_market::v141-c-R007","paper":"47-electricity_hydrogen_market","record":{"rule_id":"v141-c-R007","mechanism_id":"v141-a-M01","name":"Consumer participation","process_stage":"participation","market_meaning":"Load participation is conditional on the iteration's local electricity price being strictly lower than the DisCo selling price. Scope: Electricity LEM; Load participation in iteration r-1 at time slot t. Condition: The LEM electricity price satisfies λ_t^{L,(r-1)} \u003c λ_t^{DS}, the DisCo selling price. Household Loads may choose portfolios of electricity purchases from the DisCo and the LEM according to their own utility function. Scope: Household Loads; electricity purchasing options. HVs may purchase hydrogen from the HS or in the LEM. Scope: HVs; hydrogen purchasing options. The HSSA may purchase electricity from both the DisCo and the LEM. Scope: The HSSA acting as an electricity buyer.","independence_rationale":"Relations governed by the approved function participation.consumer under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["participation.consumer","pricing.local"],"E":[{"edge_id":"v141-c-R007-E001","source":"participation.consumer","target":"pricing.local","type":"conditional_on","constraint_ids":["v141-c-R007-C001"],"evidence_ids":["v141-b-g01-E14","v141-b-g02-e12"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Electricity LEM; Load participation in iteration r-1 at time slot t. | HVs; hydrogen purchasing options. | Household Loads; electricity purchasing options. | The HSSA acting as an electricity buyer.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14","v141-b-g02-e12"]},"x":[],"theta":[{"parameter_id":"v141-c-R007-theta-lambda-L-prev","symbol":"\\lambda_t^{L,(r-1)}","meaning":"LEM electricity price at time slot t cleared in iteration r-1; the prior local price used in the Load participation condition.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/kWh","indices":["t","r"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E14","v141-b-g02-e12"]},{"parameter_id":"v141-c-R007-theta-lambda-DS","symbol":"\\lambda_t^{DS}","meaning":"DisCo electricity selling price at time slot t; the outside-option purchase price used as the strict upper threshold in the Load participation condition.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/kWh","indices":["t"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E14","v141-b-g02-e12"]}],"phi":[{"constraint_id":"v141-c-R007-C001","kind":"logical","role":"core","statement":"Load participation is conditional on the iteration's local electricity price being strictly lower than the DisCo selling price. Scope: Electricity LEM; Load participation in iteration r-1 at time slot t. Condition: The LEM electricity price satisfies λ_t^{L,(r-1)} \u003c λ_t^{DS}, the DisCo selling price.","expression":"\\lambda_t^{L,(r-1)} \u003c \\lambda_t^{DS}","formalization_origin":"source","template_id":null,"members":["participation.consumer","pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R007-theta-lambda-L-prev","v141-c-R007-theta-lambda-DS"],"evidence_ids":["v141-b-g01-E14","v141-b-g02-e12"]},{"constraint_id":"v141-c-R007-C002","kind":"procedural","role":"core","statement":"Household Loads may choose portfolios of electricity purchases from the DisCo and the LEM according to their own utility function. Scope: Household Loads; electricity purchasing options.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.consumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E03"]},{"constraint_id":"v141-c-R007-C003","kind":"procedural","role":"core","statement":"HVs may purchase hydrogen from the HS or in the LEM. Scope: HVs; hydrogen purchasing options.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.consumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E03"]},{"constraint_id":"v141-c-R007-C004","kind":"procedural","role":"core","statement":"The HSSA may purchase electricity from both the DisCo and the LEM. Scope: The HSSA acting as an electricity buyer.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.consumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E03"]}],"pi":[{"evidence_id":"v141-b-g01-E03","location":{"location_id":"src-3c8f4fd002-p03-c2r2__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. System and Problem Description","anchor_text":"hy Vs nd Fig. 1. Overall view of the LEM. hy- The on Directions of power and hydrogen ﬂows are demon","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Directions of power and hydrogen flows are demonstrated. Renewable DGs with zero marginal production costs sell electricity to the DisCo or the LEM. Loads are households in this paper, including flexible tasks, non-flexible tasks and EVs. Each household decides on portfolios in purchasing electricity from the DisCo and LEM based on its own utility function. The HSSA can either purchase or sell electricity with both the DisCo and the LEM. Furthermore, it can purchase hydrogen from the HS and sell hydrogen to the LEM. HVs purchase hydrogen either from the HS or in the LEM. Note that the HS is assumed to acquire hydrogen directly from hydrogen-producing companies, instead of by electrolyzing water. Otherwise, the HS can be considered as the HSSA."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-3c8f4fd002-p05-c2r3__v141-a-M01-bidding","page":5,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":", p y 24) P i,tDGdeal,(r−1) at the price of λL,(r−1)t in the r −1th iteration, then the offering par","equation_id":"(33)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Similarly, for Load j, the bidding parameters are \\lambda_{j,t}^{Loadbid,(r)} = \\begin{cases} \\lambda_t^{DS}, & \\text{if } P_{j,t}^{Loadbid,(r)} \\in S_{j,t}^{Load1,(r)} \\\\ \\lambda_t^{L,(r-1)}, & \\text{if } P_{j,t}^{Loadbid,(r)} \\in S_{j,t}^{Load2,(r)} \\end{cases} \\quad (33) where S_{j,t}^{Load1,(r)} = [0, \\frac{1}{N_s}\\sum_s P_{j,t,s}^{Load,(r)} - P_{j,t}^{Loaddeal,(r-1)}], S_{j,t}^{Load2,(r)} = [\\frac{1}{N_s}\\sum_s P_{j,t,s}^{Load,(r)} - P_{j,t}^{Loaddeal,(r-1)}, \\frac{1}{N_s}\\sum_s P_{j,t,s}^{Load,(r)}]. Also note that \\lambda_t^{L,(r-1)} \u003c \\lambda_t^{DS}, otherwise the Load would not participate in the r-1th iteration of LEM."},{"evidence_id":"v141-b-g02-e12","location":{"location_id":"src-3c8f4fd002-p05-c2r3__v141-a-M01-bidding","page":5,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":", p y 24) P i,tDGdeal,(r−1) at the price of λL,(r−1)t in the r −1th iteration, then the offering par","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"\\lambda_{j,t}^{Loadbid,(r)} = \\lambda_t^{DS} \\text{ if } P_{j,t}^{Loadbid,(r)} \\in S_{j,t}^{Load1,(r)}; \\lambda_{j,t}^{Loadbid,(r)} = \\lambda_t^{L,(r-1)} \\text{ if } P_{j,t}^{Loadbid,(r)} \\in S_{j,t}^{Load2,(r)} (33) where S_{j,t}^{Load1,(r)} = [0, \\frac{1}{N_s}\\sum_s P_{j,t,s}^{Load,(r)} - P_{j,t}^{Loaddeal,(r-1)}], S_{j,t}^{Load2,(r)} = [\\frac{1}{N_s}\\sum_s P_{j,t,s}^{Load,(r)} - P_{j,t}^{Loaddeal,(r-1)}, \\frac{1}{N_s}\\sum_s P_{j,t,s}^{Load,(r)}]. Also note that \\lambda_t^{L,(r-1)} \u003c \\lambda_t^{DS}, otherwise the Load would not participate in the r-1th iteration of LEM."},{"evidence_id":"v141-b-g01-E02","location":{"location_id":"src-3c8f4fd002-p02-c1r2__v141-a-M01-bidding","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"P Electricity consumed by non interruptible and me non-deferrable tasks of Load (kWh). are P Loadid ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"P^{Aoffer} Offering amount of HSSA (kWh). P^{DGD} Electricity sold to DisCo by DG (kWh). P^{DGL} Electricity sold in LEM by DG (kWh). P^{DGoffer} Offering amount of DG (kWh). P^{DGdeal} Accepted amount of DG (kWh). P^{Load} Electricity consumed by Load (kWh). P^{LoadD} Electricity purchased from DisCo by Load (kWh). P^{LoadL} Electricity purchased in LEM by Load (kWh). P^{Loadnind} Electricity consumed by non-interruptible and non-deferrable tasks of Load (kWh). P^{Loadid} Electricity consumed by interruptible and deferrable tasks of Load (kWh). P^{Loadnid} Electricity consumed by non-interruptible and deferrable tasks of Load (kWh). P^{Loadbid} Bidding amount of Load (kWh). P^{Loaddeal} Accepted amount of Load (kWh). Q^{HAL} Hydrogen sold in LEM of HSSA (kg). Q^{HAS} Hydrogen purchased from hydrogen station of HSSA (kg). Q^{HVL} Hydrogen purchased in LEM of HV (kg). Q^{HVS} Hydrogen purchased from hydrogen station of HV (kg). Q^{HVP} Total purchased hydrogen of HV (kg). Q^{HVU} Total consumed hydrogen of HV (kg). Q^{HVbid} Bidding amount of hydrogen of HV (kg). λ^{Abid} Bidding price of HSSA (€ /kWh). λ^{Aoffer} Offering price of HSSA (€ /kWh). λ^{LnA} Electricity price in LEM without HSSA (€/kWh). λ^{L} Electricity price in LEM (€ /kWh). λ^{HL} Hydrogen price in LEM (€ /kg). λ^{DGoffer} Offering price of DG (€ /kWh). λ^{Loadbid} Bidding price of Load (€ /kWh). λ^{HVbid} Bidding price of HV (€ /kg). ρ^{HV}, ρ^{A} Pressure of hydrogen tank of HV/HSSA (Pa). u^{AP}, u^{AS} Binaries indicating operation mode of HSSA. u^{nid} Binary indicating operation mode of non-interruptible and deferrable tasks of Load. C^{A} Cost of HSSA (€). C^{HV} Cost of HV (€). C^{Load} Cost of Load (€). U^{DG} Utility of DG (€). U^{LM}, U^{LMA} Social welfare of LEM without/with HSSA (€)."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"No source-defined design-selection or operational decision variable is stated for this participation condition. The rule checks prior participation eligibility using the prior LEM price and the DisCo selling price; introducing a binary Load participation variable would not be source-grounded.","empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"participation.consumer","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E14","quote":"Also note that \\lambda_t^{L,(r-1)} \u003c \\lambda_t^{DS}, otherwise the Load would not participate in the r-1th iteration of LEM."},{"evidence_id":"v141-b-g02-e12","quote":"Also note that \\lambda_t^{L,(r-1)} \u003c \\lambda_t^{DS}, otherwise the Load would not participate in the r-1th iteration of LEM."}],[{"evidence_id":"v141-b-g01-E03","quote":"Loads are households in this paper, including flexible tasks, non-flexible tasks and EVs. Each household decides on portfolios in purchasing electricity from the DisCo and LEM based on its own utility function."}],[{"evidence_id":"v141-b-g01-E03","quote":"HVs purchase hydrogen either from the HS or in the LEM."}],[{"evidence_id":"v141-b-g01-E03","quote":"The HSSA can either purchase or sell electricity with both the DisCo and the LEM."}]],"C2_formalization":{"graph_sha256":"d61b41e0f86e5b96ae1ddab2f87db5e76b6c5e2eda8244009ffc60b392adaf77","applicability":"formalized","reason":"The core participation condition has an explicit source inequality, λ_t^{L,(r-1)} \u003c λ_t^{DS}, quoted in the supplied equation-(33) evidence. C001 is formalized as that threshold condition. C002-C004 remain procedural purchasing-option permissions with no algebraic expression in the supplied quotations. The prior-cleared LEM price is treated as a given local-scope input to the participation check, and the DisCo selling price as the outside-option comparator; no unsupported binary participation variable is introduced. The supplied evidence remains unreviewed.","bindings":[{"object_id":"v141-c-R007-C001","node_ids":["participation.consumer","pricing.local"],"edge_ids":["v141-c-R007-E001"],"rationale":"The frozen edge encodes that consumer participation is conditional on the local price. The expression is exactly the source threshold condition on that edge: the prior LEM electricity price must be strictly below the DisCo selling price."},{"object_id":"v141-c-R007-theta-lambda-L-prev","node_ids":["pricing.local"],"edge_ids":["v141-c-R007-E001"],"rationale":"This is the prior-cleared local electricity price appearing on the pricing side of the participation condition. It is a given input for the participation check in iteration r-1, not a new LEM decision variable introduced by this rule."},{"object_id":"v141-c-R007-theta-lambda-DS","node_ids":["pricing.local"],"edge_ids":["v141-c-R007-E001"],"rationale":"The DisCo selling price is the comparator in the same threshold condition. The graph has no separate outside-option price node, so this source-supported comparator is bound to the existing pricing.local node and the participation conditional_on edge; this does not assert that the DisCo price is itself the LEM clearing price."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"5588fb11a3454a2d70226f3904117d2958f82fad43bf158435e3b367b684df0f","delivery_payload_sha256":"efea0caefdf8ad72fbd6523c973fd1266968c3621a894e3419a51ffc833f0709","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"d61b41e0f86e5b96ae1ddab2f87db5e76b6c5e2eda8244009ffc60b392adaf77","scientific_correctness_verified":false}},"quarantined_references":[]}});
